def _env_first(*names: str) -> Optional[str]:
    for n in names:
        v = os.environ.get(n)
        if v is not None and str(v).strip() != "":
            return str(v).strip()
    return None


def _bool_from_env(name: str, default: bool) -> bool:
    v = os.environ.get(name)
    if v is None:
        return default
    v = v.strip().lower()
    if v in {"1", "true", "yes", "y", "on"}:
        return True
    if v in {"0", "false", "no", "n", "off"}:
        return False
    return default


def _int_from_env(name: str, default: int) -> int:
    v = os.environ.get(name)
    if v is None:
        return default
    try:
        return int(v.strip())
    except Exception:
        return default


def _float_from_env(name: str, default: float) -> float:
    v = os.environ.get(name)
    if v is None:
        return default
    try:
        return float(v.strip())
    except Exception:
        return default


def _clamp_float(x: float, lo: float, hi: float) -> float:
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def _clamp_int(x: int, lo: int, hi: int) -> int:
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def build_config(args: argparse.Namespace) -> AppConfig:
    api_key = args.api_key or _env_first("ZAI_API_KEY", "ZHIPUAI_API_KEY",
                                         "BIGMODEL_API_KEY", "ZHIPU_API_KEY",
                                         "API_KEY")
    if not api_key:
        raise SystemExit(
            "Missing API key. Set ZAI_API_KEY (or BIGMODEL_API_KEY / ZHIPUAI_API_KEY) or pass --api-key."
