    base_url = args.base_url or _env_first(
        "ZAI_BASE_URL",
        "BIGMODEL_BASE_URL") or ""
    model = args.model or "glm-4.7"
    temperature = _clamp_float(args.temperature, 0.0, 1.0)
    top_p = _clamp_float(args.top_p, 0.01, 1.0)
    max_tokens = _clamp_int(args.max_tokens, 1, 131072)
    stream = bool(args.stream)
    tool_stream = bool(args.tool_stream)
    thinking_enabled = bool(args.thinking_enabled)
    clear_thinking = bool(args.clear_thinking)
    use_web_search_tool = bool(args.web_search_tool)
