def _json_dumps_compact(obj: Any) -> str:
    return json.dumps(obj,
                      ensure_ascii=False,
                      separators=(",", ":"),
                      sort_keys=False)


def _safe_parse_json(s: str) -> Any:
    s = s.strip()
    if s == "":
        return {}
    return json.loads(s)


_ALLOWED_AST_NODES = (
    ast.Expression,
    ast.UnaryOp,
    ast.BinOp,
    ast.Add,
    ast.Sub,
    ast.Mult,
    ast.Div,
    ast.FloorDiv,
    ast.Mod,
    ast.Pow,
    ast.USub,
    ast.UAdd,
    ast.Constant,
    ast.Load,
    ast.Call,
    ast.Name,
    ast.Tuple,
    ast.List,
)

_ALLOWED_FUNCS: Dict[str, Callable[..., Any]] = {
    "abs": abs,
    "round": round,
}


def _safe_calculate(expression: str) -> float:
    try:
        tree = ast.parse(expression, mode="eval")
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")
    for node in ast.walk(tree):
        if not isinstance(node, _ALLOWED_AST_NODES):
            raise ValueError("Disallowed expression element.")
        if isinstance(node, ast.Call):
            if not isinstance(node.func,
                              ast.Name) or node.func.id not in _ALLOWED_FUNCS:
                raise ValueError("Disallowed function call.")
        if isinstance(node, ast.Name):
            if node.id not in _ALLOWED_FUNCS:
                raise ValueError("Disallowed name.")
    compiled = compile(tree, "<expr>", "eval")
    value = eval(compiled, {"__builtins__": {}}, dict(_ALLOWED_FUNCS))
    if isinstance(value, (int, float)):
        return float(value)
    raise ValueError("Expression did not evaluate to a number.")


def _resolve_host_ips(hostname: str) -> List[str]:
    try:
        import socket
        infos = socket.getaddrinfo(hostname, None, proto=socket.IPPROTO_TCP)
        addrs = []
        for info in infos:
            addr = info[4][0]
            if addr not in addrs:
                addrs.append(addr)
        return addrs
    except Exception:
        return []


def _is_private_address(ip_str: str) -> bool:
    try:
        ip = ip_address(ip_str)
    except Exception:
        return True
    for net in _PRIVATE_NETWORKS:
        if ip in net:
            return True
    return False


def _validate_public_url(url: str) -> str:
    url = url.strip()
    if not url:
        raise ValueError("URL is empty.")
    parsed = httpx.URL(url)
    if parsed.scheme not in {"http", "https"}:
        raise ValueError("Only http/https URLs are allowed.")
    host = parsed.host
    if not host:
        raise ValueError("Invalid URL host.")
    if re.fullmatch(r"\[?[0-9a-fA-F:.]+\]?", host):
        host_clean = host.strip("[]")
        if _is_private_address(host_clean):
            raise ValueError("Private or reserved IPs are not allowed.")
    else:
        ips = _resolve_host_ips(host)
        if not ips:
            raise ValueError("Could not resolve host.")
        for ip in ips:
            if _is_private_address(ip):
                raise ValueError("Private or reserved IPs are not allowed.")
    return str(parsed)


def _http_get_text(url: str,
                   timeout_total_s: float = 30.0,
                   timeout_connect_s: float = 5.0,
                   max_bytes: int = 1000000) -> str:
    safe_url = _validate_public_url(url)
    timeout = httpx.Timeout(timeout=timeout_total_s, connect=timeout_connect_s)
    with httpx.Client(timeout=timeout,
                      follow_redirects=True,
                      headers={"User-Agent": "glm-4.7-cli/1.0"}) as client:
        r = client.get(safe_url)
        r.raise_for_status()
        content = r.content
        if len(content) > max_bytes:
            content = content[:max_bytes]
        try:
            return content.decode(r.encoding or "utf-8", errors="replace")
        except Exception:
            return content.decode("utf-8", errors="replace")


def _open_meteo_geocode(location: str) -> Dict[str, Any]:
    q = location.strip()
    if not q:
        raise ValueError("location is empty")
    url = ""
    params = {"name": q, "count": 1, "language": "en", "format": "json"}
    with httpx.Client(timeout=httpx.Timeout(timeout=20.0, connect=5.0),
                      follow_redirects=True,
                      headers={"User-Agent": "glm-4.7-cli/1.0"}) as client:
        r = client.get(url, params=params)
        r.raise_for_status()
        data = r.json()
    results = data.get("results") or []
    if not results:
        raise ValueError("location not found")
    first = results[0]
    return {
        "name": first.get("name"),
        "country": first.get("country"),
        "admin1": first.get("admin1"),
        "latitude": first.get("latitude"),
        "longitude": first.get("longitude"),
        "timezone": first.get("timezone"),
    }


def _open_meteo_weather(lat: float, lon: float) -> Dict[str, Any]:
    url = ""
    params = {"latitude": lat, "longitude": lon, "current_weather": "true"}
    with httpx.Client(timeout=httpx.Timeout(timeout=20.0, connect=5.0),
                      follow_redirects=True,
                      headers={"User-Agent": "glm-4.7-cli/1.0"}) as client:
        r = client.get(url, params=params)
        r.raise_for_status()
        return r.json()


def tool_calculate(arguments: Dict[str, Any]) -> Dict[str, Any]:
    expr = str(arguments.get("expression", "")).strip()
    if not expr:
        raise ValueError("expression is required")
    value = _safe_calculate(expr)
    return {"expression": expr, "result": value}


def tool_get_time(arguments: Dict[str, Any]) -> Dict[str, Any]:
    tz = str(arguments.get("timezone", "")).strip()
    if tz == "":
        now = datetime.now(timezone.utc).astimezone()
        return {
            "timezone": str(now.tzinfo),
            "iso": now.isoformat(),
            "unix": int(now.timestamp())
        }
    try:
        from zoneinfo import ZoneInfo
        z = ZoneInfo(tz)
    except Exception:
        raise ValueError("invalid timezone")
    now = datetime.now(tz=z)
    return {
        "timezone": tz,
        "iso": now.isoformat(),
        "unix": int(now.timestamp())
    }


def tool_get_weather(arguments: Dict[str, Any]) -> Dict[str, Any]:
    location = str(arguments.get("location", "")).strip()
    unit = str(arguments.get("unit", "celsius")).strip().lower()
    if unit not in {"celsius", "fahrenheit"}:
        raise ValueError("unit must be celsius or fahrenheit")
    geo = _open_meteo_geocode(location)
    lat = float(geo["latitude"])
    lon = float(geo["longitude"])
    data = _open_meteo_weather(lat, lon)
    cw = data.get("current_weather") or {}
    temp_c = cw.get("temperature")
    wind_kph = cw.get("windspeed")
    weather_code = cw.get("weathercode")
    temp_out = temp_c
    temp_unit = "C"
    if temp_c is not None and unit == "fahrenheit":
        temp_out = (float(temp_c) * 9.0 / 5.0) + 32.0
        temp_unit = "F"
    return {
        "location": {
            "query": location,
            "name": geo.get("name"),
            "admin1": geo.get("admin1"),
            "country": geo.get("country"),
            "latitude": lat,
            "longitude": lon,
            "timezone": geo.get("timezone"),
        },
        "current_weather": {
            "temperature": temp_out,
            "temperature_unit": temp_unit,
            "windspeed_kph": wind_kph,
            "weathercode": weather_code,
            "time": cw.get("time"),
        },
        "source": "open-meteo.com",
    }


def tool_web_fetch(arguments: Dict[str, Any]) -> Dict[str, Any]:
    url = str(arguments.get("url", "")).strip()
    if not url:
        raise ValueError("url is required")
    max_bytes = int(arguments.get("max_bytes", 200000))
    max_bytes = _clamp_int(max_bytes, 1, 1000000)
    text = _http_get_text(url,
                          timeout_total_s=30.0,
                          timeout_connect_s=5.0,
                          max_bytes=max_bytes)
    return {"url": url, "max_bytes": max_bytes, "content": text}


def build_function_tools() -> Tuple[List[Dict[str, Any]], Dict[str, Callable[
    [Dict[str, Any]], Dict[str, Any]]]]:
    tools: List[Dict[str, Any]] = []
    registry: Dict[str, Callable[[Dict[str, Any]], Dict[str, Any]]] = {}

    def add(name: str, description: str, parameters: Dict[str, Any],
            fn: Callable[[Dict[str, Any]], Dict[str, Any]]) -> None:
        tools.append({
            "type": "function",
            "function": {
                "name": name,
                "description": description,
                "parameters": parameters,
            },
        })
        registry[name] = fn

    add(
        "calculate",
        "Evaluate a basic arithmetic expression safely and return a numeric result.",
        {
            "type": "object",
            "properties": {
                "expression": {
                    "type":
                    "string",
                    "description":
                    "Arithmetic expression, e.g. (2+3)*4, 10/3, 2**8"
                },
            },
            "required": ["expression"],
        },
        tool_calculate,
    )

    add(
        "get_time",
        "Get the current time. If timezone is provided, it must be an IANA timezone like Europe/Budapest.",
        {
            "type": "object",
            "properties": {
                "timezone": {
                    "type":
                    "string",
                    "description":
                    "IANA timezone name, e.g. Europe/Budapest. Optional."
                },
            },
            "required": [],
        },
        tool_get_time,
    )

    add(
        "get_weather",
        "Get current weather for a location using Open-Meteo (no API key required).",
        {
            "type": "object",
            "properties": {
                "location": {
                    "type": "string",
                    "description": "City or place name, e.g. Budapest"
                },
                "unit": {
                    "type": "string",
                    "enum": ["celsius", "fahrenheit"]
                },
            },
            "required": ["location"],
        },
        tool_get_weather,
    )

    add(
        "web_fetch",
        "Fetch the text content of a public URL (http/https only). Private/reserved IPs are blocked.",
        {
            "type": "object",
            "properties": {
                "url": {
                    "type": "string",
                    "description":
                    "Public URL starting with http:// or https://"
                },
                "max_bytes": {
                    "type":
                    "integer",
                    "description":
                    "Maximum bytes to download (1..1000000). Default 200000."
                },
            },
            "required": ["url"],
        },
        tool_web_fetch,
    )

    return tools, registry


