        },
        tool_get_time,
    )

    add(
        "get_weather",
        "Get current weather for a location using Open-Meteo (no API key required).",
        {
            "type": "object",
            "properties": {
                "location": {
                    "type": "string",
                    "description": "City or place name, e.g. Budapest"
                },
                "unit": {
                    "type": "string",
                    "enum": ["celsius", "fahrenheit"]
                },
            },
            "required": ["location"],
        },
        tool_get_weather,
    )

    add(
        "web_fetch",
        "Fetch the text content of a public URL (http/https only). Private/reserved IPs are blocked.",
        {
            "type": "object",
            "properties": {
                "url": {
                    "type": "string",
                    "description":
                    "Public URL starting with http:// or https://"
                },
                "max_bytes": {
                    "type":
                    "integer",
                    "description":
                    "Maximum bytes to download (1..1000000). Default 200000."
                },
            },
            "required": ["url"],
        },
        tool_web_fetch,
    )

    return tools, registry


def build_web_search_tool() -> List[Dict[str, Any]]:
    return [{
        "type": "web_search",
        "web_search": {
            "search_result": True,
        },
    }]


def _make_thinking(cfg: AppConfig) -> Dict[str, Any]:
    thinking_type = "enabled" if cfg.thinking_enabled else "disabled"
    return {"type": thinking_type, "clear_thinking": bool(cfg.clear_thinking)}


def _make_response_format(cfg: AppConfig) -> Dict[str, Any]:
    return {"type": cfg.response_format}


def _new_request_id() -> str:
    return str(uuid.uuid4())


def _normalize_tool_calls(tool_calls: Any) -> List[Dict[str, Any]]:
    if tool_calls is None:
        return []
    if isinstance(tool_calls, list):
        out: List[Dict[str, Any]] = []
        for tc in tool_calls:
            if tc is None:
                continue
            if isinstance(tc, dict):
                out.append(tc)
            else:
                try:
                    out.append(tc.model_dump())
                except Exception:
                    out.append(json.loads(tc.json()))
        return out
    try:
        return [tool_calls.model_dump()]
    except Exception:
        return [json.loads(tool_calls.json())]


def _append_assistant_message(messages: List[Dict[str, Any]], content: str,
                              reasoning_content: str,
                              tool_calls: List[Dict[str, Any]]) -> None:
    msg: Dict[str, Any] = {"role": "assistant"}
    if content != "":
        msg["content"] = content
    if reasoning_content != "":
        msg["reasoning_content"] = reasoning_content
    if tool_calls:
        msg["tool_calls"] = tool_calls
    messages.append(msg)


def _append_tool_message(messages: List[Dict[str, Any]], tool_call_id: str,
                         content: str) -> None:
    messages.append({
        "role": "tool",
        "tool_call_id": tool_call_id,
        "content": content
    })


def _tool_call_fields(tc: Dict[str, Any]) -> Tuple[str, str, str]:
    tc_id = str(tc.get("id") or "")
    fn = tc.get("function") or {}
    fn_name = str(fn.get("name") or "")
    fn_args = fn.get("arguments")
    if isinstance(fn_args, str):
        args_str = fn_args
    else:
        args_str = _json_dumps_compact(fn_args) if fn_args is not None else ""
    return tc_id, fn_name, args_str


def _execute_tool_call(registry: Dict[str, Callable[[Dict[str, Any]],
                                                    Dict[str, Any]]],
                       name: str, args_str: str) -> str:
    if name not in registry:
        raise ValueError(f"Unknown tool: {name}")
    if args_str.strip() == "":
        args = {}
    else:
        args = _safe_parse_json(args_str)
        if not isinstance(args, dict):
            raise ValueError("Tool arguments must be a JSON object.")
    result = registry[name](args)
    return _json_dumps_compact({"ok": True, "result": result})


def _render_error_payload(err: Exception) -> str:
    return _json_dumps_compact({
        "ok": False,
        "error": {
            "type": err.__class__.__name__,
            "message": str(err)
        }
    })


def _stream_chat_completion(
        client: Any, params: Dict[str, Any],
        print_reasoning: bool) -> Tuple[str, str, List[Dict[str, Any]]]:
    response = client.chat.completions.create(**params)
    content_parts: List[str] = []
    reasoning_parts: List[str] = []
    tool_calls_acc: Dict[str, Dict[str, Any]] = {}
    tool_calls_by_index: Dict[int, str] = {}
    printed_any = False
    printed_reasoning_any = False

    for chunk in response:
        if not getattr(chunk, "choices", None):
            continue
        choice = chunk.choices[0]
        delta = getattr(choice, "delta", None)
        if delta is None:
            continue

        rc = getattr(delta, "reasoning_content", None)
        if rc:
            reasoning_parts.append(rc)
            if print_reasoning:
                if not printed_reasoning_any and rc.strip():
                    sys.stdout.write("\n")
                    sys.stdout.flush()
                    printed_reasoning_any = True
                sys.stdout.write(rc)
                sys.stdout.flush()

        c = getattr(delta, "content", None)
        if c:
            content_parts.append(c)
            if not printed_any and c.strip():
                if print_reasoning and printed_reasoning_any:
                    sys.stdout.write("\n\n")
                printed_any = True
            sys.stdout.write(c)
            sys.stdout.flush()

        dtc = getattr(delta, "tool_calls", None)
        if dtc:
            for tc in dtc:
                try:
                    tci = getattr(tc, "index", None)
                    tc_id = getattr(tc, "id", None)
                    tc_type = getattr(tc, "type", None)
                    fn = getattr(tc, "function", None)
                    fn_name = getattr(fn, "name",
                                      None) if fn is not None else None
                    fn_args = getattr(fn, "arguments",
                                      None) if fn is not None else None
                except Exception:
                    try:
                        tci = tc.get("index")
                        tc_id = tc.get("id")
                        tc_type = tc.get("type")
                        fn = tc.get("function") or {}
                        fn_name = fn.get("name")
                        fn_args = fn.get("arguments")
                    except Exception:
                        continue
                if tc_id:
                    key = str(tc_id)
                elif tci is not None:
                    if int(tci) in tool_calls_by_index:
                        key = tool_calls_by_index[int(tci)]
                    else:
                        key = f"tool_{uuid.uuid4().hex}"
                        tool_calls_by_index[int(tci)] = key
                else:
                    key = f"tool_{uuid.uuid4().hex}"
                if key not in tool_calls_acc:
                    tool_calls_acc[key] = {
                        "id": key,
                        "type": str(tc_type or "function"),
                        "function": {
                            "name": "",
                            "arguments": ""
                        }
                    }
                entry = tool_calls_acc[key]
                if fn_name:
                    entry["function"]["name"] = str(fn_name)
                if fn_args is not None:
                    entry["function"]["arguments"] = str(entry["function"].get(
                        "arguments", "")) + str(fn_args)

    if printed_any or printed_reasoning_any:
        sys.stdout.write("\n")
        sys.stdout.flush()
    tool_calls = list(tool_calls_acc.values())
    return "".join(content_parts), "".join(reasoning_parts), tool_calls


def _sync_chat_completion(
        client: Any,
        params: Dict[str, Any]) -> Tuple[str, str, List[Dict[str, Any]]]:
    resp = client.chat.completions.create(**params)
    if not getattr(resp, "choices", None):
        return "", "", []
    msg = resp.choices[0].message
    content = getattr(msg, "content", "") or ""
    reasoning_content = getattr(msg, "reasoning_content", "") or ""
    tool_calls = _normalize_tool_calls(getattr(msg, "tool_calls", None))
    return content, reasoning_content, tool_calls


def run_model_with_tools(
    client: Any,
    cfg: AppConfig,
    messages: List[Dict[str, Any]],
    tools_payload: List[Dict[str, Any]],
    registry: Dict[str, Callable[[Dict[str, Any]], Dict[str, Any]]],
) -> Dict[str, Any]:
    iterations = 0
    while True:
        iterations += 1
        if iterations > cfg.max_tool_iterations:
            raise RuntimeError("Exceeded max tool iterations.")
        params: Dict[str, Any] = {
            "model": cfg.model,
            "messages": messages,
            "temperature": cfg.temperature,
            "top_p": cfg.top_p,
            "max_tokens": cfg.max_tokens,
            "do_sample": True,
            "thinking": _make_thinking(cfg),
            "response_format": _make_response_format(cfg),
            "request_id": _new_request_id(),
        }
        if tools_payload:
            params["tools"] = tools_payload
            params["tool_choice"] = "auto"
        if cfg.stream:
            params["stream"] = True
            if tools_payload and cfg.tool_stream:
                params["tool_stream"] = True
            content, reasoning_content, tool_calls = _stream_chat_completion(
                client, params, cfg.print_reasoning)
        else:
            params["stream"] = False
            content, reasoning_content, tool_calls = _sync_chat_completion(
                client, params)
            if content:
                sys.stdout.write(content + "\n")
                sys.stdout.flush()

        _append_assistant_message(messages, content, reasoning_content,
                                  tool_calls)

        if not tool_calls:
            return {
                "content": content,
                "reasoning_content": reasoning_content,
                "tool_calls": []
            }

        for tc in tool_calls:
            tc_id, fn_name, fn_args = _tool_call_fields(tc)
            if tc_id == "":
                tc_id = f"tool_{uuid.uuid4().hex}"
            try:
                tool_result = _execute_tool_call(registry, fn_name, fn_args)
            except Exception as e:
                tool_result = _render_error_payload(e)
            _append_tool_message(messages, tc_id, tool_result)


def _read_stdin_all() -> str:
    data = sys.stdin.read()
    if data is None:
        return ""
    return data


def _load_image_as_data_url(path: str) -> str:
    with open(path, "rb") as f:
        b = f.read()
    encoded = base64.b64encode(b).decode("ascii")
    ext = os.path.splitext(path)[1].lower()
    if ext in {".jpg", ".jpeg"}:
        mime = "image/jpeg"
    elif ext == ".png":
        mime = "image/png"
    elif ext == ".webp":
        mime = "image/webp"
    else:
        mime = "application/octet-stream"
    return f"data:{mime};base64,{encoded}"


def build_initial_messages(system_prompt: str) -> List[Dict[str, Any]]:
    msgs: List[Dict[str, Any]] = []
    if system_prompt.strip():
        msgs.append({"role": "system", "content": system_prompt})
    return msgs


def main() -> None:
    parser = argparse.ArgumentParser(add_help=True)
    parser.add_argument("--api-key", default=None)
    parser.add_argument("--base-url", default=None)
    parser.add_argument("--model", default="glm-4.7")
    parser.add_argument("--temperature",
                        type=float,
                        default=_float_from_env("GLM_TEMPERATURE", 1.0))
    parser.add_argument("--top-p",
                        type=float,
                        default=_float_from_env("GLM_TOP_P", 1.0))
    parser.add_argument("--max-tokens",
                        type=int,
                        default=_int_from_env("GLM_MAX_TOKENS", 131072))
    parser.add_argument("--stream",
                        action="store_true",
                        default=_bool_from_env("GLM_STREAM", True))
    parser.add_argument("--tool-stream",
                        action="store_true",
                        default=_bool_from_env("GLM_TOOL_STREAM", True))
    parser.add_argument("--thinking-enabled",
                        action="store_true",
                        default=_bool_from_env("GLM_THINKING_ENABLED", True))
    parser.add_argument("--clear-thinking",
                        action="store_true",
                        default=_bool_from_env("GLM_CLEAR_THINKING", True))
    parser.add_argument("--web-search-tool",
                        action="store_true",
                        default=_bool_from_env("GLM_USE_WEB_SEARCH_TOOL",
                                               True))
    parser.add_argument("--function-tools",
                        action="store_true",
                        default=_bool_from_env("GLM_USE_FUNCTION_TOOLS", True))
    parser.add_argument("--response-format",
                        default=_env_first("GLM_RESPONSE_FORMAT") or "text")
    parser.add_argument("--timeout-total-s",
                        type=float,
                        default=_float_from_env("GLM_TIMEOUT_TOTAL_S", 300.0))
    parser.add_argument("--timeout-connect-s",
                        type=float,
                        default=_float_from_env("GLM_TIMEOUT_CONNECT_S", 5.0))
    parser.add_argument("--max-retries",
                        type=int,
                        default=_int_from_env("GLM_MAX_RETRIES", 2))
    parser.add_argument("--max-tool-iterations",
                        type=int,
                        default=_int_from_env("GLM_MAX_TOOL_ITERATIONS", 10))
    parser.add_argument("--print-reasoning",
                        action="store_true",
                        default=_bool_from_env("GLM_PRINT_REASONING", False))
    parser.add_argument("--system",
                        default=_env_first("GLM_SYSTEM_PROMPT") or "")
    parser.add_argument("--prompt", default=None)
    parser.add_argument("--stdin", action="store_true", default=False)
    parser.add_argument("--image", default=None)
    parser.add_argument("--history-file",
                        default=_env_first("GLM_HISTORY_FILE") or "")
    parser.add_argument("--no-save-history",
                        action="store_true",
                        default=False)
    args = parser.parse_args()

    cfg = build_config(args)
    client = create_client(cfg)

    function_tools, registry = build_function_tools()
    tools_payload: List[Dict[str, Any]] = []
    if cfg.use_function_tools:
        tools_payload.extend(function_tools)
    if cfg.use_web_search_tool:
        tools_payload.extend(build_web_search_tool())

    messages: List[Dict[str, Any]] = build_initial_messages(args.system)

    if args.history_file.strip():
        try:
            with open(args.history_file, "r", encoding="utf-8") as f:
                loaded = json.load(f)
            if isinstance(loaded, list):
                messages.extend(
                    [m for m in loaded if isinstance(m, dict) and "role" in m])
        except Exception:
            pass

    def save_history() -> None:
        if args.no_save_history:
            return
        if not args.history_file.strip():
            return
        try:
            with open(args.history_file, "w", encoding="utf-8") as f:
                json.dump(messages, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    def add_user_message(text: str, image_path: Optional[str]) -> None:
        if image_path:
            data_url = _load_image_as_data_url(image_path)
            messages.append({
                "role":
                "user",
                "content": [
                    {
                        "type": "text",
                        "text": text
                    },
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": data_url
                        }
                    },
                ],
            })
        else:
            messages.append({"role": "user", "content": text})

    if args.stdin:
        prompt_text = _read_stdin_all()
        prompt_text = prompt_text.strip("\ufeff")
        add_user_message(prompt_text, args.image)
        try:
            run_model_with_tools(client, cfg, messages, tools_payload,
                                 registry)
        finally:
            save_history()
        return

    if args.prompt is not None:
        add_user_message(str(args.prompt), args.image)
        try:
            run_model_with_tools(client, cfg, messages, tools_payload,
                                 registry)
        finally:
            save_history()
        return

    try:
        while True:
            try:
                user_in = input("> ")
            except EOFError:
                break
            user_in = user_in.strip()
            if user_in == "":
                continue
            if user_in.lower() in {"/exit", "/quit", "exit", "quit"}:
                break
            add_user_message(user_in, args.image)
            try:
                run_model_with_tools(client, cfg, messages, tools_payload,
                                     registry)
            except zai.core.APIAuthenticationError as e:
                sys.stderr.write(str(e) + "\n")
                sys.stderr.flush()
                break
            except zai.core.APIReachLimitError as e:
                sys.stderr.write(str(e) + "\n")
                sys.stderr.flush()
                time.sleep(1.0)
            except zai.core.APITimeoutError as e:
                sys.stderr.write(str(e) + "\n")
                sys.stderr.flush()
            except zai.core.APIStatusError as e:
                sys.stderr.write(str(e) + "\n")
                sys.stderr.flush()
            except Exception as e:
                sys.stderr.write(str(e) + "\n")
                sys.stderr.flush()
            save_history()
    finally:
        save_history()


if __name__ == "__main__":
    main()
